/bin/sh -lc "cd /workspace/.scotty/capture && node - <<'NODE'
const { chromium } = require('playwright');
const fs = require('fs/promises');
const path = require('path');

(async () => {
  const outDir = '/workspace/.scotty/captures';
  const videoDir = path.join(outDir, 'video');
  await fs.mkdir(videoDir, { recursive: true });
  const screenshotPath = path.join(outDir, 'counter-page-390x844.png');
  const finalVideoPath = path.join(outDir, 'counter-clicks-390x844.webm');

  const browser = await chromium.launch({ headless: true });

  const shotContext = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const shotPage = await shotContext.newPage();
  await shotPage.goto('http://localhost:5173', { waitUntil: 'networkidle' });
  await shotPage.screenshot({ path: screenshotPath, fullPage: false });
  await shotContext.close();

  const videoContext = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 1,
    recordVideo: { dir: videoDir, size: { width: 390, height: 844 } },
  });
  const page = await videoContext.newPage();
  await page.goto('http://localhost:5173', { waitUntil: 'networkidle' });
  const button = page.getByRole('button');
  await page.waitForTimeout(500);
  for (let i = 0; i < 5; i++) {
    await button.click();
    await page.waitForTimeout(650);
  }
  await page.waitForTimeout(1200);
  const rawVideo = await page.video().path();
  await videoContext.close();
  await browser.close();
  await fs.copyFile(rawVideo, finalVideoPath);
  console.log(JSON.stringify({ screenshotPath, finalVideoPath }, null, 2));
})();
NODE"

